{
 "summary": "The Lean theorem states that for any group α and any subgroup s, Nat.card s divides Nat.card α. There is no finiteness assumption, so it is formally stronger than the paper's statement. For finite α it is exactly Lagrange's theorem. For infinite α, Nat.card α = 0 and every natural number divides 0, so the extra cases hold only via the junk value. This is harmless.",
 "glossary": [
  {"decl": "Nat.card", "line": 6, "plain": "cardinality of a type as a natural number (|H|, |G|), with value 0 for infinite types", "standard_concept": "order of a finite group", "matches_standard": "partly", "note": "It agrees with the order on finite groups and is 0 on infinite ones. The paper only concerns finite G, so this does not matter."}
 ],
 "lean_claims": [
  {"theorem": "stmt", "line": 6, "plain": "For every group α (finite or not) and every subgroup s ≤ α, Nat.card s ∣ Nat.card α. When α is finite this says |s| divides |α|; when α is infinite the right side is 0 and the statement is trivially true."}
 ],
 "paper_claims": [
  {"ref": "Theorem (Lagrange)", "plain": "If G is a finite group and H ≤ G, then |H| divides |G|."}
 ],
